INSERT INTO `plants` (`id`, `category_id`, `local_name`, `scientific_name`, `slug`, `description`, `health_benefits`, `processing_potential`, `image_path`, `is_published`, `created_at`, `updated_at`) VALUES
	(1, 1, 'Beras', 'Oryza sativa', 'beras', 'Beras merupakan bahan pangan pokok yang menjadi sumber energi utama bagi masyarakat Indonesia.', 'Mengandung karbohidrat yang memberikan energi bagi tubuh.', 'Simpan nasi matang tidak lebih dari 6 jam pada suhu ruang untuk mencegah pertumbuhan bakteri.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(2, 2, 'Ayam', 'Gallus gallus domesticus', 'ayam', 'Daging ayam merupakan sumber protein hewani yang banyak dikonsumsi.', 'Mengandung protein tinggi untuk pertumbuhan dan perbaikan jaringan tubuh.', 'Masak ayam hingga suhu internal minimal 75°C untuk membunuh bakteri.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(3, 2, 'Telur Ayam', 'Gallus gallus domesticus ovum', 'telur-ayam', 'Telur ayam adalah bahan pangan yang kaya protein dan sering digunakan dalam berbagai masakan.', 'Mengandung protein lengkap dan berbagai vitamin penting.', 'Masak telur hingga matang sempurna dan simpan di lemari pendingin.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(4, 3, 'Tempe', 'Glycine max fermented', 'tempe', 'Tempe adalah makanan fermentasi berbahan dasar kedelai yang populer di Indonesia.', 'Mengandung protein nabati, serat, dan mineral.', 'Simpan tempe di kulkas dan masak hingga matang sebelum dikonsumsi.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(5, 3, 'Tahu', 'Glycine max tofu', 'tahu', 'Tahu merupakan produk olahan kedelai yang mudah diolah menjadi berbagai hidangan.', 'Sumber protein nabati yang baik bagi tubuh.', 'Simpan dalam air bersih di kulkas dan ganti air secara berkala.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(6, 4, 'Bayam', 'Amaranthus tricolor', 'bayam', 'Bayam merupakan sayuran hijau yang kaya zat besi.', 'Baik untuk kesehatan darah dan meningkatkan daya tahan tubuh.', 'Cuci dengan air mengalir sebelum dimasak.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(7, 4, 'Wortel', 'Daucus carota', 'wortel', 'Wortel adalah sayuran akar yang kaya vitamin A.', 'Baik untuk kesehatan mata dan sistem imun.', 'Kupas dan cuci sebelum dimasak.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(8, 4, 'Tomat', 'Solanum lycopersicum', 'tomat', 'Tomat sering digunakan dalam berbagai masakan dan sambal.', 'Mengandung vitamin C dan antioksidan likopen.', 'Cuci sebelum dipotong dan gunakan pisau bersih.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(9, 5, 'Pisang', 'Musa paradisiaca', 'pisang', 'Pisang merupakan buah yang mudah ditemukan dan kaya energi.', 'Mengandung kalium yang baik untuk kesehatan jantung.', 'Simpan pada suhu ruang hingga matang.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(10, 5, 'Pepaya', 'Carica papaya', 'pepaya', 'Pepaya adalah buah tropis yang kaya vitamin dan serat.', 'Baik untuk pencernaan dan kesehatan kulit.', 'Cuci sebelum dipotong dan simpan di lemari pendingin setelah matang.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(11, 6, 'Singkong', 'Manihot esculenta', 'singkong', 'Singkong merupakan umbi yang sering dijadikan makanan pokok alternatif.', 'Mengandung karbohidrat tinggi sebagai sumber energi.', 'Masak hingga matang untuk menghilangkan senyawa beracun alami.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(12, 6, 'Kentang', 'Solanum tuberosum', 'kentang', 'Kentang adalah umbi yang sering digunakan dalam berbagai hidangan.', 'Mengandung karbohidrat, vitamin C, dan kalium.', 'Simpan di tempat sejuk dan hindari paparan cahaya langsung.', NULL, 1, '2026-03-10 01:44:43', '2026-03-10 01:44:43'),
	(14, 7, 'Beras merah', 'Oryza sativa var. indica', 'beras-merah', 'Beras merah termasuk kelompok serealia yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Menyediakan energi sebagai sumber karbohidrat utama.', 'Simpan dalam kondisi bersih dan masak hingga matang sebelum disajikan.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
	(15, 7, 'Jagung kuning', 'Zea mays', 'jagung-kuning', 'Jagung kuning termasuk kelompok serealia yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Menyediakan energi sebagai sumber karbohidrat utama.', 'Simpan dalam kondisi bersih dan masak hingga matang sebelum disajikan.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
	(16, 8, 'Ubi jalar', 'Ipomoea batatas', 'ubi-jalar', 'Ubi jalar termasuk kelompok umbi yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Menyediakan energi sebagai sumber karbohidrat utama.', 'Simpan dalam kondisi bersih dan masak hingga matang sebelum disajikan.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
	(17, 9, 'Mangga', 'Mangifera indica', 'mangga', 'Mangga termasuk kelompok buah yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Mendukung variasi vitamin, mineral, dan serat dalam menu seimbang.', 'Cuci dengan air mengalir dan gunakan alat potong yang bersih.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
	(18, 9, 'Jeruk', 'Citrus sinensis', 'jeruk', 'Jeruk termasuk kelompok buah yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Mendukung variasi vitamin, mineral, dan serat dalam menu seimbang.', 'Cuci dengan air mengalir dan gunakan alat potong yang bersih.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
	(19, 10, 'Kubis', 'Brassica oleracea var. capitata', 'kubis', 'Kubis termasuk kelompok sayuran yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Mendukung variasi vitamin, mineral, dan serat dalam menu seimbang.', 'Cuci dengan air mengalir dan gunakan alat potong yang bersih.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
	(20, 10, 'Kacang panjang', 'Vigna unguiculata sesquipedalis', 'kacang-panjang', 'Kacang panjang termasuk kelompok sayuran yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Mendukung variasi vitamin, mineral, dan serat dalam menu seimbang.', 'Cuci dengan air mengalir dan gunakan alat potong yang bersih.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
	(21, 11, 'Daging sapi', 'Bos taurus', 'daging-sapi', 'Daging sapi termasuk kelompok bahan pangan hewani yang sering digunakan dalam menu harian dan edukasi gizi SafeFood.', 'Menyumbang protein dan mineral penting untuk kebutuhan tubuh.', 'Simpan pada suhu dingin, hindari kontaminasi silang, dan masak hingga matang aman.', NULL, 1, '2026-03-10 03:15:14', '2026-03-10 03:15:14'),
